import {COOKIE_URL,hex,localOrigin,validTicket,ticketText} from './protocol.mjs';

export async function verifyTicket(ticket,origin,secret,cryptoImpl=crypto,now=Date.now()){
  if(!hex(secret)||!validTicket(ticket,origin,now))return false;
  const bytes=value=>Uint8Array.from(value.match(/../g),v=>parseInt(v,16));
  const key=await cryptoImpl.subtle.importKey('raw',bytes(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);
  return cryptoImpl.subtle.verify('HMAC',key,bytes(ticket.proof),new TextEncoder().encode(ticketText(ticket)));
}
export function cookieHeader(cookies){
  const selected=new Map();
  for(const cookie of cookies){
    if(!['google.com','aistudio.google.com'].includes(cookie.domain?.replace(/^\./,''))||cookie.partitionKey)continue;
    if(!/^[!#$%&'*+.^_`|~0-9A-Za-z-]+$/.test(cookie.name)||typeof cookie.value!=='string'||/[;\r\n\0]/.test(cookie.value))continue;
    if(!selected.has(cookie.name))selected.set(cookie.name,cookie.value);
  }
  if(!selected.size)throw Error('未找到 Google 登录 Cookie，请在当前浏览器登录 AI Studio 后重试');
  return [...selected].map(([name,value])=>`${name}=${value}`).join('; ');
}
export function createCaptureClient({getConnection,claim,getCookies,fetchImpl=fetch,cryptoImpl=crypto,now=Date.now}){
  const inFlight=new Set();
  return async(ticket,sender)=>{
    const origin=sender?.origin??new URL(sender?.url).origin;
    if(!localOrigin(origin)||sender.frameId!==0||sender.tab?.incognito)throw Error('只允许本机账号管理页面发起抓取');
    const connection=await getConnection(ticket?.installationId);
    if(!connection||!await verifyTicket(ticket,origin,connection.secret,cryptoImpl,now()))throw Error('扩展尚未连接此管理服务，请先点击连接扩展');
    if(inFlight.has(ticket.token))throw Error('该抓取请求已使用，请重新点击抓取');
    inFlight.add(ticket.token);
    try{
      await claim(ticket);
      const cookies=cookieHeader(await getCookies({url:COOKIE_URL}));
      let response;
      try{response=await fetchImpl(ticket.origin+'/api/browser/import',{method:'POST',redirect:'error',headers:{Authorization:'Bearer '+ticket.token,'Content-Type':'application/json'},body:JSON.stringify({cookies}),signal:AbortSignal.timeout(15000)});}
      catch{throw Error('本机管理服务连接失败，请重新打开菜单 11');}
      if(!response.ok){await response.body?.cancel();throw Error('本机管理服务未接受凭证，请重新点击抓取');}
      // Cookies never leave this function through messaging, storage, or logs.
      return {ok:true,submitted:true};
    }finally{inFlight.delete(ticket.token);}
  };
}

const el=id=>document.getElementById(id),id=location.hash.slice(1);
async function api(type){const result=await chrome.runtime.sendMessage({type,id});if(!result?.ok)throw Error(result?.error??'扩展连接失败');return result;}
const say=(message,error=false)=>{el('feedback').textContent=message;el('feedback').dataset.error=String(error);};
async function refresh(){const result=await api('inspect');el('pair').hidden=!result.pending;el('home').hidden=!!result.pending;if(result.pending){el('origin').textContent=result.pending.origin;el('identity').textContent='管理服务标识：'+result.pending.installationId.slice(0,12);}else el('count').textContent=`已连接 ${result.count} 份管理服务`;say('');}
for(const type of ['approve','cancel','forget'])el(type).onclick=async()=>{el(type).disabled=true;try{await api(type);await refresh();say(type==='approve'?'连接完成，请回账号管理页一键导入。':type==='cancel'?'已取消连接。':'已断开连接，账号凭证仍保留在 MMDB。');}catch(error){say(error.message,true);}finally{el(type).disabled=false;}};
refresh().catch(error=>say(error.message,true));

export const EXTENSION_ID='pgppfacklbmaojbefbgllmjabijlkabc';
export const EXTENSION_ORIGIN=`chrome-extension://${EXTENSION_ID}`;
export const COOKIE_URL='https://aistudio.google.com/';
export const hex=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
export function localOrigin(value){
  try{const u=new URL(value);return u.protocol==='http:'&&u.hostname==='127.0.0.1'&&Number(u.port)>0&&!u.username&&!u.password&&u.origin===value;}catch{return false;}
}
export function validTicket(value,origin,now=Date.now()){
  return value?.version===1&&hex(value.installationId)&&hex(value.token)&&hex(value.proof)&&localOrigin(value.origin)&&value.origin===origin&&Number.isSafeInteger(value.authUser)&&value.authUser>=0&&value.authUser<=99&&Number.isSafeInteger(value.expiresAt)&&value.expiresAt>now&&value.expiresAt<=now+90000;
}
export const ticketText=value=>JSON.stringify([value.version,value.installationId,value.origin,value.token,value.authUser,value.expiresAt]);

import {createCaptureClient} from './capture.mjs';
import {hex,localOrigin} from './protocol.mjs';

const connections=async()=>(await chrome.storage.local.get('connections')).connections??{};
const capture=createCaptureClient({
  getConnection:async id=>(await connections())[id],
  getCookies:details=>chrome.cookies.getAll(details),
  claim:async ticket=>{
    const previous=(await chrome.storage.session.get('used')).used??{};
    if(previous[ticket.token])throw Error('该抓取请求已使用，请重新点击抓取');
    const used=Object.fromEntries(Object.entries(previous).filter(([,expires])=>expires>Date.now()));
    used[ticket.token]=ticket.expiresAt;await chrome.storage.session.set({used});
  }
});
async function external(message,sender){
  let origin;try{origin=new URL(sender.url).origin;}catch{throw Error('无效来源');}
  if(!localOrigin(origin)||sender.frameId!==0||sender.tab?.incognito)throw Error('仅接受本机管理页请求');
  if(message?.type==='status'){const pending=(await chrome.storage.session.get('pendingPair')).pendingPair;return {ok:true,paired:!!(await connections())[message.installationId],pending:pending?.installationId===message.installationId&&pending.expiresAt>Date.now()};}
  if(message?.type==='capture')return capture(message.ticket,sender);
  if(message?.type==='pair'){
    const pair=message.pair;
    if(pair?.version!==1||!hex(pair.installationId)||!hex(pair.secret)||pair.origin!==origin)throw Error('连接请求无效');
    const current=(await chrome.storage.session.get('pendingPair')).pendingPair;
    if(current?.expiresAt>Date.now())throw Error('已有连接确认窗口，请先处理该窗口');
    const id=crypto.randomUUID();await chrome.storage.session.set({pendingPair:{...pair,id,expiresAt:Date.now()+180000}});
    await chrome.windows.create({url:chrome.runtime.getURL('connect.html')+'#'+id,type:'popup',width:500,height:490});
    return {ok:true,pending:true};
  }
  throw Error('未知操作');
}
chrome.runtime.onMessageExternal.addListener((message,sender,respond)=>{
  external(message,sender).then(respond,error=>respond({ok:false,error:error.message}));return true;
});
async function internal(message,sender){
  if(sender.id!==chrome.runtime.id||sender.url?.split('#')[0]!==chrome.runtime.getURL('connect.html'))throw Error('无效来源');
  if(message.type==='forget'){await chrome.storage.local.remove('connections');return {ok:true};}
  const pending=(await chrome.storage.session.get('pendingPair')).pendingPair;
  const valid=pending?.id===message.id&&pending.expiresAt>Date.now();
  if(message.type==='inspect')return {ok:true,count:Object.keys(await connections()).length,pending:valid?{origin:pending.origin,installationId:pending.installationId}:null};
  if(!valid)throw Error('连接请求已过期，请回管理页重新连接');
  if(message.type==='approve'){
    const saved=await connections();saved[pending.installationId]={secret:pending.secret};await chrome.storage.local.set({connections:saved});
  }else if(message.type!=='cancel')throw Error('未知操作');
  await chrome.storage.session.remove('pendingPair');return {ok:true};
}
chrome.runtime.onMessage.addListener((message,sender,respond)=>{
  internal(message,sender).then(respond,error=>respond({ok:false,error:error.message}));return true;
});

