// Read only capability metadata. Cookie values, tokens and source paths never
// leave this module or enter diagnostics; file timestamps are not login checks.
import {readFileSync,readdirSync,lstatSync} from 'node:fs';
import {join} from 'node:path';

export function createAuthMetadata(root){
  const base=join(root,'auth'),cache=new Map();
  const plain=(path,directory=false)=>{const stat=lstatSync(path);if(stat.isSymbolicLink()||(directory?!stat.isDirectory():!stat.isFile()))throw Error('Invalid credential path');return stat;};
  const read=path=>{if(plain(path).size>2*1024*1024)throw Error('Oversized credential file');return JSON.parse(readFileSync(path,'utf8'));};
  return ()=>{
    const result=new Map(),seen=new Set();
    try{
      plain(base,true);
      for(const entry of readdirSync(base,{withFileTypes:true})){
        if(!entry.isDirectory()||entry.isSymbolicLink())continue;
        const directory=join(base,entry.name);seen.add(directory);
        try{
          plain(directory,true);
          const configPath=join(directory,'account.json'),storagePath=join(directory,'storage-state.json');
          const a=plain(configPath),b=plain(storagePath),stamp=[a.mtimeMs,a.ctimeMs,a.size,b.mtimeMs,b.ctimeMs,b.size].join(':');
          let item=cache.get(directory);
          if(item?.stamp!==stamp){
            const config=read(configPath),state=read(storagePath),extension=state.aistudio2api;
            if(typeof config.label!=='string')continue;
            const sameAccount=typeof extension?.source?.email==='string'&&extension.source.email.toLowerCase()===config.label.toLowerCase();
            const oauth=sameAccount&&typeof extension?.oauth?.refresh_token==='string'&&!!extension.oauth.refresh_token&&typeof extension.oauth.gaia_id==='string'&&!!extension.oauth.gaia_id;
            const capability=oauth?'saved_oauth':sameAccount&&extension?.source?.browser==='chrome'?'chrome_source':'cookie_only';
            item={stamp,id:config.label.toLowerCase(),capability};cache.set(directory,item);
          }
          // Ambiguous identities cannot be advertised as capable of renewal.
          result.set(item.id,result.has(item.id)?'unknown':item.capability);
        }catch{cache.delete(directory);}
      }
    }catch{cache.clear();}
    for(const key of cache.keys())if(!seen.has(key))cache.delete(key);
    return result;
  };
}

export function authView(member,capability='unknown'){
  const value=member.auth??{};
  return {capability,automatic:capability==='saved_oauth'||capability==='chrome_source',
    lastVerifiedAt:value.lastVerifiedAt??null,lastCheckedAt:value.lastCheckedAt??null,
    verifiedBy:value.verifiedBy??null,lastFailure:value.lastFailure??null,
    failures:value.failures??0,nextCheckAt:value.nextCheckAt??null};
}

import {spawn} from 'node:child_process';
import {isManagerURL} from './portal.mjs';

// Wait until the OS has accepted the browser launch before the CMD window exits.
// Keep the private local URL out of the PowerShell command line and error output.
export async function openManagerPage(url,{platform=process.platform,spawnImpl=spawn,timeoutMs=15000}={}){
  if(!isManagerURL(url))throw Error('本机管理地址无效，未打开浏览器');
  const command=platform==='win32'?'powershell.exe':platform==='darwin'?'open':'xdg-open';
  const args=platform==='win32'?['-NoProfile','-NonInteractive','-Command',"$ErrorActionPreference='Stop'; Start-Process -FilePath $env:MMDB_MANAGER_URL"]:[url];
  return new Promise((resolve,reject)=>{
    let child,settled=false,timer;
    const finish=error=>{if(settled)return;settled=true;clearTimeout(timer);error?reject(error):resolve();};
    try{child=spawnImpl(command,args,{windowsHide:true,stdio:'ignore',...(platform==='win32'?{env:{...process.env,MMDB_MANAGER_URL:url}}:{})});}
    catch{finish(Error('无法启动系统浏览器，请用下面的本机地址手动打开'));return;}
    child.once('error',()=>finish(Error('无法启动系统浏览器，请用下面的本机地址手动打开')));
    child.once('close',code=>finish(code===0?null:Error('系统未能打开浏览器，请用下面的本机地址手动打开')));
    timer=setTimeout(()=>{finish(Error('等待浏览器打开超时，请用下面的本机地址手动打开'));try{child.kill();}catch{}},timeoutMs);
  });
}

// Metadata journal shared by the relay, account pool and supervisor. No message,
// URL, credential, stack or upstream error text is accepted by this boundary.
import {mkdirSync,readFileSync,writeFileSync,appendFileSync,renameSync,readdirSync,statSync,lstatSync,unlinkSync} from 'node:fs';
import {join} from 'node:path';
import {randomUUID,randomBytes,createHmac} from 'node:crypto';
import {processAlive} from './headless-lock.mjs';

const DAY=86400000,MiB=1024*1024;
const FILE=/^events-\d{4}-\d{2}-\d{2}-\d+-[a-f0-9-]+\.jsonl$/;
const token=value=>typeof value==='string'&&/^[-a-zA-Z0-9_.:]{1,160}$/.test(value)?value:undefined;
const number=value=>Number.isFinite(value)&&value>=0?value:undefined;
const metrics={usage:['promptTokenCount','candidatesTokenCount','thoughtsTokenCount','totalTokenCount','cachedContentTokenCount','toolUsePromptTokenCount'],requestCounts:['total','inputRead','answer','continuation','retry','probe'],timings:['firstByteMs','firstBodyMs','firstClientTextMs','queuedMs','preparingMs','headersMs'],generation:['temperature','topP','topK','maxOutputTokens','nativeOutputBudget'],images:['count','bytes']};
const strings=['requestId','dispatchId','source','model','requestedModel','accountRef','fromAccountRef','reason','status','code','stage','backend','finishReason','inputReadMode','continuationMode'];
const numbers=['pid','sequence','attempt','round','httpStatus','elapsedMs','retryAt','firstBodyMs','firstByteMs'];
export function cleanDiagnostic(value){
  const out={v:1};
  if(!value||typeof value!=='object'||!token(value.type))return null;
  out.type=value.type;out.id=token(value.id)??randomUUID();out.at=number(value.at)??Date.now();
